use super::*;

#[test]
fn mask_strings_basic() {
    assert_eq!(
        mask_strings(r#"let s = "if x > 0";"#, &[]),
        r#"let s = "        ";"#
    );
    assert_eq!(
        mask_strings(r#"let c = '{'; if x {"#, &[]),
        r#"let c = ' '; if x {"#
    );
    assert_eq!(
        mask_strings(r#"let s = "he said \"hi\"";"#, &[]),
        r#"let s = "              ";"#
    );
}

#[test]
fn mask_strings_empty() {
    assert_eq!(mask_strings("", &[]), "");
}

#[test]
fn mask_strings_no_strings() {
    assert_eq!(mask_strings("let x = 42;", &[]), "let x = 42;");
}

#[test]
fn mask_strings_raw_string() {
    // Python raw string: r prefix is just an identifier char, "..." is masked normally
    let result = mask_strings(r#"x = r"if|for|while""#, &[]);
    assert!(!result.contains("if|for|while"));
    assert!(result.contains("r")); // the r prefix is preserved
}

#[test]
fn mask_strings_unclosed_string() {
    // Unclosed string: mask everything after the quote
    assert_eq!(mask_strings(r#"let s = "hello"#, &[]), r#"let s = "     "#);
}

#[test]
fn mask_strings_with_line_comment() {
    // Unmatched quote in comment should NOT confuse string masking
    assert_eq!(
        mask_strings("x = 5; // don't do this", &["//"]),
        "x = 5;                 "
    );
}

#[test]
fn mask_strings_comment_after_string() {
    // String is masked, then comment is masked
    assert_eq!(
        mask_strings(r#"x = "hello"; // it's ok"#, &["//"]),
        r#"x = "     ";           "#
    );
}

#[test]
fn mask_strings_comment_marker_inside_string() {
    // Comment marker inside a string should NOT trigger comment masking
    assert_eq!(
        mask_strings(r#"x = "http://foo"; if y"#, &["//"]),
        r#"x = "          "; if y"#
    );
}

#[test]
fn read_and_classify_blanks_inline_tests_when_they_are_excluded() {
    let (_dir, path) = crate::test_blocks::tests::source_with_test_module();
    let spec = crate::loc::language::detect(&path).unwrap();
    let code = |exclude_tests| {
        let (lines, kinds) = read_and_classify(&path, spec, exclude_tests)
            .unwrap()
            .unwrap();
        assert_eq!(lines.len(), kinds.len());
        kinds.iter().filter(|k| **k == LineKind::Code).count()
    };
    assert_eq!(code(true), 3);
    assert_eq!(code(false), 14);
}

fn write(dir: &Path, name: &str, text: &str) -> std::path::PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, text).unwrap();
    path
}

#[test]
fn generated_file_by_header_marker() {
    let dir = tempfile::tempdir().unwrap();
    let cases = [
        (
            "types_gen.go",
            "// Code generated by stringer; DO NOT EDIT.\n\npackage demo\n",
        ),
        (
            "msg_pb.py",
            "# Generated by the protocol buffer compiler.  DO NOT EDIT!\n",
        ),
        ("Schema.cs", "// <auto-generated />\nnamespace App;\n"),
        ("relay.js", "/**\n * @generated SignedSource<<abc>>\n */\n"),
        (
            "parser.c",
            "/* A Bison parser, made by GNU Bison 3.8.2.  */\n",
        ),
        (
            "lexer.c",
            "#line 1 \"lexer.c\"\n\n/* A lexical scanner generated by flex */\n",
        ),
        (
            "bundle.js",
            "var App = (() => {\n  var __defProp = Object.defineProperty;\n",
        ),
    ];
    for (name, text) in cases {
        assert!(is_generated_file(&write(dir.path(), name, text)), "{name}");
    }
}

#[test]
fn generated_file_marker_must_be_in_the_head() {
    let dir = tempfile::tempdir().unwrap();
    let mut text = "fn f() {}\n".repeat(HEAD_LINES);
    text.push_str("// Code generated by x. DO NOT EDIT.\n");
    assert!(!is_generated_file(&write(dir.path(), "late.rs", &text)));
}

#[test]
fn generated_file_by_source_map() {
    let dir = tempfile::tempdir().unwrap();
    let commented = write(
        dir.path(),
        "app.mjs",
        "export const a = 1;\n//# sourceMappingURL=app.mjs.map\n",
    );
    assert!(is_generated_file(&commented));

    let beside = write(dir.path(), "lib.js", "module.exports = 1;\n");
    assert!(!is_generated_file(&beside));
    write(dir.path(), "lib.js.map", "{}");
    assert!(is_generated_file(&beside));
}

#[test]
fn hand_written_file_is_not_generated() {
    let dir = tempfile::tempdir().unwrap();
    let path = write(
        dir.path(),
        "main.go",
        "// Package main generates reports. Edit with care.\npackage main\n",
    );
    assert!(!is_generated_file(&path));
    assert!(!is_generated_file(&dir.path().join("missing.rs")));
}
